// =============================================================================
// mfcc_roms.v -- the two small ROMs the MFCC top needs.
//
//   window_rom    : 480 x 16 unsigned Q1.15 Hann taps (generated by
//                   scripts/golden/gen_mfcc_golden.py)
//   mfcc_norm_rom : 40 x 56 {B[31:0], A[23:0]}, the per-coefficient affine map
//                   code = (A*dct + B) >> 20 that folds normalisation and UINT8
//                   quantisation into one multiply-add
//
// Both are combinational reads; they are small enough to become LUTRAM.
// =============================================================================
`timescale 1ns / 1ps

module window_rom #(
    parameter integer DEPTH = 512,
    parameter         INIT_FILE = "mem/preprocessing/hann_q15.mem"
) (
    input  wire [8:0]  addr,
    output wire [15:0] dout
);
    (* rom_style = "distributed" *) reg [15:0] mem [0:DEPTH-1];
    assign dout = mem[addr];
    initial begin
        if (INIT_FILE != "") $readmemh(INIT_FILE, mem);
    end
endmodule

module mfcc_norm_rom #(
    parameter integer DEPTH = 64,
    parameter         INIT_FILE = "mem/preprocessing/mfcc_norm.mem"
) (
    input  wire [5:0]  addr,
    output wire [55:0] dout
);
    (* rom_style = "distributed" *) reg [55:0] mem [0:DEPTH-1];
    assign dout = mem[addr];
    initial begin
        if (INIT_FILE != "") $readmemh(INIT_FILE, mem);
    end
endmodule
